// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Signed-delta publication failures that can never succeed against the current base generation must be typed as
 * permanent so the store escalates to a base rebuild instead of retrying the identical failure forever.
 */
class FrontierDeltaPermanentFailureTest {

	private static final long MIB = 1024L * 1024L;

	@Test
	void exceedingTheDeltaEnvelopeIsAPermanentFailure(@TempDir Path directory) throws Exception {
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(16L * MIB, 16, 32, 256, MIB);
		FrontierStatisticsHeapGovernor governor = governor();
		FrontierStatisticsManifest base = FrontierStatisticsBuilder.build(directory, 1L, -1L, snapshot(), governor,
				config);
		FrontierStatisticsBuildConfig tinyEnvelope = withDeltaBudget(config, 1024L);

		FrontierStatisticsException failure = assertThrows(FrontierStatisticsException.class,
				() -> FrontierStatisticsDeltaBuilder.build(directory, base, mutations(base), governor, tinyEnvelope));

		assertEquals(FrontierFallbackReason.MEMORY_PRESSURE, failure.fallbackReason());
		assertTrue(failure.requiresBaseRebuild(),
				"a delta that exceeds its persistent envelope can never be published against this base: "
						+ failure.getMessage());
	}

	@Test
	void omniDimensionMismatchIsATypedPermanentFailure(@TempDir Path directory) throws Exception {
		FrontierStatisticsBuildConfig narrow = FrontierStatisticsBuildConfig.testing(16L * MIB, 16, 32, 256, MIB);
		FrontierStatisticsBuildConfig wide = FrontierStatisticsBuildConfig.testing(16L * MIB, 32, 32, 256, MIB);
		FrontierStatisticsHeapGovernor governor = governor();
		FrontierStatisticsManifest base = FrontierStatisticsBuilder.build(directory, 1L, -1L, snapshot(), governor,
				narrow);
		assertEquals(16, base.width(), "the base generation carries the Omni width it was built with");

		FrontierStatisticsException failure = assertThrows(FrontierStatisticsException.class,
				() -> FrontierStatisticsDeltaBuilder.build(directory, base, mutations(base), governor, wide));

		assertEquals(FrontierFallbackReason.MEMORY_PRESSURE, failure.fallbackReason(),
				"budget drift shrinks or widens the Omni layout; it is not shard corruption");
		assertTrue(failure.requiresBaseRebuild(), "no delta can ever apply to a base with other dimensions: "
				+ failure.getMessage());
	}

	@Test
	void matchingDimensionsStillPublishOrdinaryDeltas(@TempDir Path directory) throws Exception {
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(16L * MIB, 16, 32, 256, MIB);
		FrontierStatisticsHeapGovernor governor = governor();
		FrontierStatisticsManifest base = FrontierStatisticsBuilder.build(directory, 1L, -1L, snapshot(), governor,
				config);
		FrontierStatisticsManifest delta = FrontierStatisticsDeltaBuilder.build(directory, base, mutations(base),
				governor, config);
		assertEquals(base.coveredSequence() + 1L, delta.coveredSequence());
		assertEquals(base.width(), delta.width());
	}

	@Test
	void ordinaryTypedFailuresRemainTransient() {
		FrontierStatisticsException governorRefusal = new FrontierStatisticsException(
				FrontierFallbackReason.MEMORY_PRESSURE, "Frontier signed-delta workspace exceeds the heap governor");
		assertFalse(governorRefusal.requiresBaseRebuild());
		FrontierStatisticsException withCause = new FrontierStatisticsException(
				FrontierFallbackReason.SHARD_CORRUPT, "shard is missing", new IOException("disk"));
		assertFalse(withCause.requiresBaseRebuild());
		assertTrue(FrontierStatisticsException.permanent(FrontierFallbackReason.MEMORY_PRESSURE, "envelope")
				.requiresBaseRebuild());
		assertFalse(FrontierStatisticsException.transientFailure(FrontierFallbackReason.MEMORY_PRESSURE, "governor")
				.requiresBaseRebuild());
	}

	private static FrontierStatisticsHeapGovernor governor() {
		return new FrontierStatisticsHeapGovernor(64L * MIB, 8L * MIB, 16L * MIB, 8L * MIB);
	}

	private static List<FrontierMutation> mutations(FrontierStatisticsManifest base) {
		long sequence = base.coveredSequence() + 1L;
		return List.of(new FrontierMutation(sequence, sequence, true, true, 101L, 7L, 40_001L, 0L));
	}

	private static FrontierStatisticsBuildConfig withDeltaBudget(FrontierStatisticsBuildConfig source,
			long deltaAndManifestBudgetBytes) {
		return new FrontierStatisticsBuildConfig(source.diskBudgetBytes(), source.exactAndLinearBudgetBytes(),
				source.leafWitnessBudgetBytes(), source.joinSampleBudgetBytes(), source.adaptiveBudgetBytes(),
				deltaAndManifestBudgetBytes, source.sortMemoryBytes(), source.designLaneCount(),
				source.auditLaneCount(), source.cellCount(), source.omniDepth(), source.witnessFloorPerCell(),
				source.witnessCeilingPerCell(), source.deleteReserveFraction(), source.countMinDepth(),
				source.countMinWidth(), source.heavyPredicateCapacity(), source.hllPrecision());
	}

	private static FrontierSnapshotSource snapshot() {
		List<long[]> explicit = new ArrayList<>();
		for (int subject = 1; subject <= 50; subject++) {
			for (int row = 0; row < 20; row++) {
				explicit.add(new long[] { subject, 7L, 10_000L + subject * 100L + row, 0L });
			}
		}
		List<long[]> inferred = new ArrayList<>();
		for (int row = 0; row < 10; row++) {
			inferred.add(new long[] { 1000L + row, 9L, 30_000L + row, 1L });
		}
		return new ListSnapshot(77L, explicit, inferred);
	}

	private static final class ListSnapshot implements FrontierSnapshotSource {

		private final long epoch;
		private final List<long[]> explicit;
		private final List<long[]> inferred;

		private ListSnapshot(long epoch, List<long[]> explicit, List<long[]> inferred) {
			this.epoch = epoch;
			this.explicit = List.copyOf(explicit);
			this.inferred = List.copyOf(inferred);
		}

		@Override
		public long snapshotEpoch() {
			return epoch;
		}

		@Override
		public long scan(boolean explicitPlane, RawQuadSink sink) throws IOException {
			List<long[]> rows = explicitPlane ? explicit : inferred;
			for (long[] row : rows) {
				sink.accept(row[0], row[1], row[2], row[3]);
			}
			return rows.size();
		}

		@Override
		public boolean contains(long subjectId, long predicateId, long objectId, long contextId,
				boolean explicitPlane) {
			return (explicitPlane ? explicit : inferred).stream()
					.anyMatch(row -> row[0] == subjectId && row[1] == predicateId && row[2] == objectId
							&& row[3] == contextId);
		}

		@Override
		public void close() {
		}
	}
}
